In this paper we consider a class of optimization problems of the
following type: \begin{equation}\label{prob_ori_1}
\min_{x\in\mathbb{R}^n}~F(x):=f(x)+g(x), \end{equation} where both
functions $f,g\colon\R^n\to\oR:=(-\infty,\infty]$ are proper,
convex, and lower semicontinuous (l.s.c.), while being structurally
different from each other. Namely, $f$ is assumed to be twice
continuously differentiable with the Lipschitz continuous gradient
$\nabla f$ on its domain. On the other hand, $g$ is merely
continuous on its domain; see Assumption~\ref{assumptions_f} for the
precise formulations. It has been well recognized that model
\eqref{prob_ori_1}, known as a {\em composite convex optimization
problem}, frequently appears in a variety of applications including,
e.g., machine learning, signal processing, and statistics, where $f$
is a {\em loss function} and $g$ is a {\em regularizer}; we keep
this terminology here. Note that problem \eqref{prob_ori_1} contains
in fact implicit constraints written as $x\in\O:=\dom g$.


\begin{equation}\label{lin} \min_{x\in\mathbb{R}^n}~l_k(x) +
\frac{1}{2t}\|x-x_k\|^2 \;\; \text{with} \;\; l_k(x):=f(x^k)+\nabla
f(x^k)^T(x-x^k)+g(x), \end{equation}

\begin{equation}\label{subproblem}
\min_{x\in\mathbb{R}^n}~q_k(x):=f(x^k)+\nabla
f(x^k)^T(x-x^k)+\frac{1}{2}(x-x^k)^TH_k(x-x^k)+g(x), \end{equation}

\begin{assumption}\label{assumptions_f} Impose the following properties of the loss function and the regularizer in \eqref{prob_ori_1}:
\begin{itemize}
\item[{\bf(i)}] Both functions $f,g:{\R^n}\rightarrow (-\infty,\infty]$ are proper, l.s.c., and convex.

\item[{\bf(ii)}] The \revise{effective} domain of the loss function $\dom f:=\{x~|~f(x)<\infty\}$ is open, and $f(x)$ is twice continuously differentiable on a closed set $\Omega\supset \dom f$.

\item[{\bf(iii)}] The regularizer $g(x)$ is continuous on its domain and $\varnothing \ne\dom g \subset\dom f$.

\item[{\bf(iv)}] The gradient $\nabla f(x)$ is Lipschitz continuous on a closed set $\Omega$ from {\rm(ii)} with Lipschitz constant $L_1>0$.

\item[{\bf(v)}] Problem \eqref{prob_ori_1} has a nonempty solution set ${\cal{X}^*}:=\arg\min_{x\in\R^n}F(x)$ with the optimal value $F^*$.
\end{itemize}
\end{assumption}

\begin{equation}\label{prox-map}
\hbox{Prox}_{g}(u):={\rm argmin}\Big\{g(x)+\frac{1}{2}\|x-u\|^2\;\Big|\;x\in\R^n\Big\},\quad u\in\R^n,
\end{equation}

\begin{equation}\label{prox-gra}
\mathcal{G}(x):=x-\mathrm{Prox}_{g}\big(x-\nabla f(x)\big),\quad x\in\R^n,
\end{equation}

Given a current iterate $x^k$ for each $k=0,1,\ldots$, we select a {\em positive semidefinite matrix} $B_k$ as an arbitrary approximation of the Hessian $\nabla^2 f(x^k)$ satisfying the {\em standing
boundedness assumption}:
\begin{equation}\label{assum_B_bounded}
\mbox{ there exists }\;M\ge 0\;\mbox{ such that }\;\|B_k\|\le M\;\mbox{ whenever }\;k=0,1,\ldots.
\end{equation}
If the gradient mapping $\nabla f$ is uniformly Lipschitz continuous along the sequence of iterates with constant $L_1$, then \eqref{assum_B_bounded} holds for $B_k=\nabla^2 f(x^k)$ with $M=L_1$.
In the general case of $B_k$, pick any constants $c>0$ and $\rho\in(0,1]$ and, using the prox-regular mapping \eqref{prox-gra}, consider the positive number $\alpha_k:=c\|\mathcal{G}(x^k)\|^{\rho}$
and define the {\em quasi-Newton approximation} of the Hessian of $f$ at $x^k$ by
\begin{equation}\label{alg-app}
H_k:=B_k+\alpha_kI\;\mbox{ for all }\;k=0,1,\ldots,
\end{equation}
which is a positive definite matrix. Then similarly to \cite{byrd2016inexact}, but with the different approximation \eqref{alg-app}, denote
\begin{equation}\label{opt-mes}
r_k(x):=x-\mathrm{Prox}_{g}\left(x-\nabla f(x^k)-H_k(x-x^k)\right)
\end{equation}
and select $\hat{x}^k$ as an {\em approximate minimizer} of the quadratic {\em subproblem} for \eqref{prob_ori_1} given by
\begin{equation}\label{subproblem1}
\min_{x\in\mathbb{R}^n}~q_k(x):=f(x^k)+\nabla f(x^k)^T(x-x^k)+\frac{1}{2}(x-x^k)H_k(x-x^k)+g(x)
\end{equation}
with the {\em residual} number $\|r_k(\hat x^k)\|$ measuring the approximate optimality of $\hat x^k$ in \eqref{subproblem1}. Observing that $\|r_k(\hat{x}^k)\|=0$ if and only if $\hat{x}^k$ is an
{\em exact} solution to subproblem \eqref{subproblem1}, we use the nonnegative number {\color{black} $\|r_k(\hat{x}^k)\|$}
with $r_k(x)$ taken from \eqref{opt-mes} as the {\em optimality measure} of $\hat x^k$ in subproblem \eqref{subproblem1}. Adapting the scheme of \cite{byrd2016inexact} in our new setting, let us impose
the following two estimates as {\em inexact conditions} for choosing $\hat{x}^k$ as an approximate solution to subproblem \eqref{subproblem1}:
{\color{black}\begin{equation}\label{inexact_condition_1}
\|r_k(\hat{x}^k)\|\le\eta_k\|\mathcal{G}(x^k)\|\;\mbox{ and }\;q_k(\hat{x}^k)\le q_k(x^k)
\end{equation}}%
with the parameter $\eta_k:=\nu\min\{1,\|\mathcal{G}(x^k)\|^{\varrho}\}$ defined via \eqref{opt-mes} and some numbers $\nu\in[0,1)$ and $\varrho>0$. \revise{Since any exact solution to subproblem \eqref{subproblem1} always fulfills the two inexact conditions in \eqref{inexact_condition_1}, a point $\hat x^k$ satisfying \eqref{inexact_condition_1} always exists. For many application problems, the mapping $\mathrm{Prox}_{g}$ is easy to calculate, thus inexact conditions \eqref{inexact_condition_1} can be readily verified.


\begin{algorithm}
\caption{Proximal Newton-type method}\label{Newton}
\begin{algorithmic}[1]
\State Choose $x^0\in\mathbb{R}^n$, $0<\theta,\sigma,\gamma<1$, $C>F(x^0)$, $\revise{\bar{\alpha}}, c>0$, and $\rho\in(0,1]$.
\For{$k=0,1,\ldots$}{
\begin{itemize}
\item[1.] Update the approximation of the Hessian matrix $B_k$.
\item[2.] Form the quadratic model \eqref{subproblem} with $H_k:=B_k+\alpha_kI$ and \revise{$\alpha_k:=\min \left\{ \bar{\alpha}, c\|\mathcal{G}(x^k)\|^{\rho}\right\} $  }.
\item[3.] Obtain an inexact solution $\hat{x}^k$ of \eqref{subproblem} satisfying the conditions in \eqref{inexact_condition_1}.
\item[4.] If $k=0$, let $\vartheta_1:=\mathcal{G}(x^0)$ and go to Step~5. For $k\ge 1$, if $\|\mathcal{G}(\hat{x}^k)\|\le\sigma\vartheta_k$ and $F(\hat{x}^k)\le C$, let $t_k:=1$, $\vartheta_{k+1}:=
\|\mathcal{G}(\hat{x}^k)\|$,
and go to Step~6. Otherwise, let $\vartheta_{k+1}:=\vartheta_k$ and go to Step~5.
\item[5.] Perform a backtracking line search along the direction $d^k:=\hat{x}^k-x^k$ by setting $t_k:=\gamma^{m_k}$, where $m_k$ is the smallest nonnegative integer $m$ such that
\begin{equation}\label{line_search}
F(x^k+\gamma^md^k)\le F(x^k)-\theta\alpha_k\gamma^m\|d^k\|^2.
\end{equation}
\item[6.] Set $x^{k+1}:=x^k+t_kd^k$.
\end{itemize}}
\EndFor
\end{algorithmic}
\end{algorithm}

\begin{equation}\label{K}
K:=\big\{0,1,\ldots\big\}\;\mbox{ and }\;K_0:=\{0\}\cup\big\{k+1\in K ~\big|~\text{Step~$5$ is not applied at iteration $k$}\big\}.
\end{equation}

