\| \mathcal{G}(x^k) - e_k\|^2 & \le \|\mathcal{G}(x^k)\|^2 -2\big\langle e_k,\mathcal{G}(x^k)\big\rangle +\|e_k\|^2+(\hat{x}^k-x^k)^TH_k(\hat{x}^k-x^k) \\
&\le\big\langle \mathcal{G}(x^k) - e_k,x^k-\hat{x}^k+H_k(x^k-\hat{x}^k)\big\rangle \\
&\le\big\| \mathcal{G}(x^k) - e_k\big\| \cdot \big\| x^k-\hat{x}^k+H_k(x^k-\hat{x}^k)\big\|.
\end{aligned}
\end{equation*}

Using again the condition $\|e_k\|\le\nu\|\mathcal{G}(x^k)\|$ together with $\|B_k\|\le M$ from \eqref{assum_B_bounded} results in
\begin{equation*}
\|\mathcal{G}(x^k)\| \le \| \mathcal{G}(x^k) - e_k\| + \|e_k\| \le(1+M+\alpha_k)\|\hat{x}^k-x^k\|+ \nu\|\mathcal{G}(x^k)\|.
\end{equation*}
Remembering the choice of $\nu\in[0, 1)$, we estimate the prox-gradient mapping \eqref{prox-gra} at the iterate $x^k$ by
\begin{equation}\label{decrease_eq2}
\|\mathcal{G}(x^k)\|\le\frac{1+M+\alpha_k}{1-\nu}\|\hat{x}^k-x^k\|.
\end{equation}

Combining the latter with \eqref{decrease_eq1} and using the choice of $\theta\in(0,1)$ yield the relationships
\begin{equation}\label{decrease_eq3}
\begin{aligned}
&F(x^k)-F(x^k+\tau d^k)-\frac{\theta\alpha_k\tau}{2}\|d^k\|^2\\
\ge~&l_k(x^k)-l_k(x^k+\tau d^k)-\frac{L_1}{2}\tau^2\|d^k\|^2-\frac{\theta\alpha_k\tau}{2}\|d^k\|^2\\
\ge~&\tau\big(l_k(x^k)-l_k(x^k+d^k)\big)-\frac{L_1}{2}\tau^2\|d^k\|^2-\frac{\theta\alpha_k\tau}{2}\|d^k\|^2\\
\ge~&(1-\theta)\tau\frac{\alpha_k}{2}\|d^k\|^2-\frac{L_1}{2}\tau^2\|d^k\|^2\\
=~&\frac{\tau}{2}\|d^k\|^2\big((1-\theta)\alpha_k-L_1\tau\big).
\end{aligned}
\end{equation}
